using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 Node3D fieldEventRoot;int fieldEventVisual=-1;
 string FieldEventName()=>FieldEvent.Kind==0?"A horde on the move":FieldEvent.Kind==1?"Hettie's trading cart":"Owen's last delivery";
 bool NearFieldEvent()=>ContentEnabled&&dungeon==null&&FieldEvent.Stage==1&&Distance(player.Position,Ground(FieldEvent.X,FieldEvent.Z))<4;
 void StartFieldEvent(int kind,Vector3 at){FieldEvent.Serial++;FieldEvent.Kind=kind;FieldEvent.Stage=1;FieldEvent.X=at.X;FieldEvent.Z=at.Z;FieldEvent.GoalX=at.X-170;FieldEvent.GoalZ=at.Z-65;FieldEvent.Remaining=kind==2?180:240;FieldEvent.Dead=0;FieldEvent.Traded=false;FieldEvent.Health=kind==2?45:90;FieldEvent.Outcome=kind==0?"Tracks cross the trail. A migrating group is approaching; you can wait, sneak around it, or intercept it.":kind==1?"Hettie has stopped her cart on the road. Her trade stock is limited; she will move on soon.":"An injured courier calls from a broken supply cart. His dressings are soaked. He needs help within three active minutes.";game.Notice=FieldEvent.Outcome;game.Persist();FeverSync();}
 void TickFieldEvent(double dt){var e=FieldEvent;if(e.Stage!=1){if(game.World.Changes.Time<e.Due)return;var p=MillPlayers().FirstOrDefault(p=>game.World.Tier(p.Body.Position.X,p.Body.Position.Z)>=2);e.Due=game.World.Changes.Time+90;if(p.Body==null)return;for(int j=0;j<24;j++){double a=j*.71,x=p.Body.Position.X+Math.Cos(a)*65,z=p.Body.Position.Z+Math.Sin(a)*65;if(game.World.Tier(x,z)>=2&&OutdoorFree(x,z)&&!InEncounterLot(x,z)&&game.World.Playable(x,z)){StartFieldEvent((int)(game.World.Hash(e.Serial+12,877)%3),Ground(x,z));break;}}return;}
  if(!NearActiveSurface(Ground(e.X,e.Z),190))return;e.Remaining=Math.Max(0,e.Remaining-dt);SpawnFieldEvent();if(e.Kind==0){int tier=game.World.Tier(e.X,e.Z),count=tier>=3?6:4;for(int j=0;j<count&&infected.Count<(CoopHost?CoopMaxEnemies:85);j++){if((e.Dead&(1<<j))!=0)continue;string id=$"field-event/{e.Serial}/horde/{j}/{game.Save.Seed}";AddEnemy(id,e.X+j*1.5,e.Z+j%2*2,tier);var z=infected.FirstOrDefault(z=>z.Id==id);if(z!=null&&z.Memory<=1){z.Target=Ground(e.GoalX,e.GoalZ);z.Memory=.8;z.Home=z.Body.Position;}}}
  if(e.Remaining<=0)FinishFieldEvent(e.Kind==0?"The migration has passed. Any infected you disturbed remain in the area.":e.Kind==1?"Hettie packed up and moved on. Her cart's tracks lead northwest.":"Owen's wounds were too much. The delivery never reached its destination.");
 }
 void FinishFieldEvent(string outcome){FieldEvent.Stage=2;FieldEvent.Outcome=outcome;FieldEvent.Due=game.World.Changes.Time+900+game.World.Hash(FieldEvent.Serial,431)%420;game.WorldDecision("field-event/"+FieldEvent.Serial,outcome);game.Notice=outcome;game.Persist();FeverSync();}
 void SpawnFieldEvent(){if(!ContentEnabled||dungeon!=null)return;var e=FieldEvent;if(GodotObject.IsInstanceValid(fieldEventRoot)){fieldEventRoot.Visible=e.Stage==1&&fieldEventVisual==e.Serial;if(fieldEventVisual==e.Serial)return;fieldEventRoot.QueueFree();fieldEventRoot=null;}if(e.Stage!=1||!NearActiveSurface(Ground(e.X,e.Z),190))return;fieldEventVisual=e.Serial;fieldEventRoot=new Node3D{Name="RoamingFieldEvent",Position=Ground(e.X,e.Z)};worldRoot.AddChild(fieldEventRoot);if(e.Kind==0){for(int j=0;j<5;j++)Box(fieldEventRoot,new(j*.4f,.03f,j*.3f),new(.12f,.04f,.25f),Ink);return;}Box(fieldEventRoot,new(0,.6f,0),new(2.3f,.3f,3),Wood,true);for(int side=-1;side<=1;side+=2)for(int j=0;j<2;j++)Tube(fieldEventRoot,new(side*1.2f,.4f,-1+j*2),new(side*1.35f,.4f,-1+j*2),.40f,Ink);for(int j=0;j<3;j++)Box(fieldEventRoot,new(-.7f+j*.7f,1,0),new(.6f,.6f,.8f),Cloth);var person=new Node3D{Name="Traveller",Position=new(2,0,0),RotationDegrees=e.Kind==2?new(0,0,60):Vector3.Zero};fieldEventRoot.AddChild(person);HumanCharacter(person,1,0,true);fieldEventRoot.AddChild(new Label3D{Text=e.Kind==1?"HETTIE / TRAVELLING TRADER":"OWEN / INJURED COURIER",Position=new(0,2.5f,0),FontSize=22,PixelSize=.006f,Billboard=BaseMaterial3D.BillboardModeEnum.Enabled});}
 bool FieldCivilianTarget(Infected enemy,float distance)=>ContentEnabled&&dungeon==null&&FieldEvent.Stage==1&&FieldEvent.Kind>0&&FieldEvent.Health>0&&Distance(enemy.Body.Position,Ground(FieldEvent.X,FieldEvent.Z))<Math.Min(distance,18)&&PursuitClear(enemy.Body.Position,Ground(FieldEvent.X,FieldEvent.Z),PursuitExclusions());
 void HurtFieldCivilian(double damage){if(FieldEvent.Stage!=1||FieldEvent.Kind==0)return;FieldEvent.Health=Math.Max(0,FieldEvent.Health-damage);if(FieldEvent.Health<=0)FinishFieldEvent(FieldEvent.Kind==1?"Hettie was killed beside her trading cart. The market is lost.":"Owen was killed before his delivery could be saved.");}
 void FieldEventAction(string op){if(!NearFieldEvent())return;var e=FieldEvent;if(op=="open"){if(CoopHost&&coopActor>0)RpcId(coopActor,nameof(CoopFieldEventPage));else ShowFieldEvent();return;}if(e.Kind==1&&op is "supplies" or "ammo"){if(e.Traded)return;if(op=="supplies"){if(game.Life.Food<3){game.Notice="Trade needs three food.";return;}game.Life.Food-=3;game.Life.Bandages+=2;game.Craft.Fuel+=2;}else{if(game.World.Tier(e.X,e.Z)<3||game.Craft.Materials[4]<8){game.Notice="Ammunition stock needs tier-three country and eight alloy.";return;}game.Craft.Materials[4]-=8;game.Craft.GiveAmmo(1,12);game.Craft.GiveAmmo(2,12);}e.Traded=true;game.Notice="Hettie packs your purchase. The rest of her stock is spoken for.";game.Persist();FeverSync();return;}
  if(e.Kind==2&&op is "help" or "take"){var t=game.World.Changes.Settlements.Where(t=>t.Index<3&&!t.Fallen).OrderBy(t=>ExpeditionGame.Distance(t.X,t.Z,e.X,e.Z)).FirstOrDefault();if(op=="help"){if(game.Life.Bandages<2||game.Life.Food<1){game.Notice="Needs two bandages and one food.";return;}game.Life.Bandages-=2;game.Life.Food--;game.Craft.Materials[5]+=2;game.Career.Gain(80);if(t!=null){t.Food+=4;t.Water+=4;RememberTown(t.Index,4,"You saved a courier carrying our supplies.");}var next=Enumerable.Range(0,ExpeditionContentSite.All.Length).FirstOrDefault(i=>!Field(i).Seen);Field(next).Seen=true;FinishFieldEvent("Owen can walk again. He leaves you his spare parts and a marked route; the settlement receives his delivery.");}else{game.Craft.Fuel+=3;game.Craft.Materials[4]+=2;if(t!=null)RememberTown(t.Index,-8,"You took the injured courier's delivery and left him behind.");FinishFieldEvent("You took Owen's spare supplies. His delivery and rescue opportunity are lost.");}return;}
 }
 void ShowFieldEvent(){var b=Panel(FieldEventName().ToUpperInvariant());Text(b,FieldEvent.Outcome+$"\nTime remaining: {FieldEvent.Remaining:0} active seconds."+(FieldEvent.Kind>0?$" Traveller health: {FieldEvent.Health:0}.":""));void Act(string title,string op){Button(b,title,()=>{CloseMenu();if(!CoopRequest("content","event:"+op))ContentAction("event:"+op);});}if(FieldEvent.Kind==1&&!FieldEvent.Traded){Act("BARTER 3 FOOD / 2 BANDAGES + 2 FUEL","supplies");Act("BARTER 8 ALLOY / RIFLE AND CARBINE AMMO / T3+","ammo");}if(FieldEvent.Kind==2){Act("TREAT OWEN / 2 BANDAGES + 1 FOOD","help");Act("TAKE HIS SUPPLIES AND LEAVE / REPUTATION LOSS","take");}Button(b,"LEAVE",CloseMenu);}
 [Rpc(MultiplayerApi.RpcMode.Authority,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)]void CoopFieldEventPage(){if(CoopClient&&FieldEvent.Stage==1)ShowFieldEvent();}
}
